def test_read_item_stats_normal_user(
    client: TestClient, normal_user_token_headers: dict[str, str]
) -> None:
    response = client.get(
        f"{settings.API_V1_STR}/items/stats", headers=normal_user_token_headers
    )
    assert response.status_code == 200
    assert response.json() == {"count": 0, "newest_title": None}

    for title in ("first", "second"):
        client.post(
            f"{settings.API_V1_STR}/items/",
            headers=normal_user_token_headers,
            json={"title": title},
        )
    response = client.get(
        f"{settings.API_V1_STR}/items/stats", headers=normal_user_token_headers
    )
    assert response.status_code == 200
    assert response.json() == {"count": 2, "newest_title": "second"}


def test_read_item_stats_superuser_counts_all_items(
    client: TestClient, superuser_token_headers: dict[str, str], db: Session
) -> None:
    create_random_item(db)
    create_random_item(db)
    response = client.get(
        f"{settings.API_V1_STR}/items/stats", headers=superuser_token_headers
    )
    assert response.status_code == 200
    content = response.json()
    assert content["count"] >= 2
    assert content["newest_title"] is not None
EOF
